//! Spec §06 `likelihoodof`: "The shape of variates of (the probability measures
//! generated by) the kernel must match the shape of the observed data", and several
//! IID observations need an explicit `iid`. Observed data of another shape or
//! structure is a static error that names both types. Only shape and structure are
//! judged, as for a density point.

use flatppl_infer::{Severity, infer};

fn errors(src: &str) -> Vec<String> {
    let mut module = flatppl_syntax::parse(src).unwrap();
    infer(&mut module)
        .into_iter()
        .filter(|d| d.severity == Severity::Error)
        .map(|d| d.message)
        .collect()
}

#[test]
fn observed_data_of_another_shape_is_refused_naming_both_types() {
    for (kernel, obs, observed, variate) in [
        (
            "functionof(Normal(mu, 1.0), mu = mu)",
            "[2.0, 3.0]",
            "array of real [2]",
            "real",
        ),
        (
            "functionof(iid(Normal(mu, 1.0), 3), mu = mu)",
            "[2.0, 3.0]",
            "array of real [2]",
            "array of real [3]",
        ),
        (
            "functionof(iid(Normal(mu, 1.0), 2), mu = mu)",
            "2.0",
            "real",
            "array of real [2]",
        ),
        (
            "functionof(Normal(mu, 1.0), mu = mu)",
            "record(x = 2.0)",
            "record",
            "real",
        ),
    ] {
        let src = format!("mu = elementof(reals)\nL = likelihoodof({kernel}, {obs})\n");
        let found = errors(&src);
        assert_eq!(found.len(), 1, "expected one error, got {found:?}\n{src}");
        for needle in [
            "`likelihoodof`: the observed data is",
            observed,
            &format!("variates of type {variate}"),
            "explicit `iid`",
            "spec §06 `likelihoodof`",
        ] {
            assert!(found[0].contains(needle), "`{needle}` not in: {}", found[0]);
        }
    }
}

#[test]
fn observed_data_of_the_variate_shape_is_accepted() {
    for (kernel, obs) in [
        ("functionof(Normal(mu, 1.0), mu = mu)", "2.0"),
        ("functionof(iid(Normal(mu, 1.0), 2), mu = mu)", "[2.0, 3.0]"),
        // Only shape counts: an integer observation of a real variate lies in the
        // support question, not the shape one.
        ("functionof(Normal(mu, 1.0), mu = mu)", "2"),
        ("functionof(Poisson.(fill(exp(mu), 2)), mu = mu)", "[1, 4]"),
    ] {
        let src = format!(
            "mu = elementof(reals)\nL = likelihoodof({kernel}, {obs})\n\
             v = logdensityof(L, record(mu = 0.5))\n"
        );
        let found = errors(&src);
        assert!(found.is_empty(), "unexpected errors: {found:?}\n{src}");
    }
}
